try:
    from ui_common import build_title
except Exception:
    def build_title(app_name, build_number=None, subtitle=None):
        title = app_name
        if build_number:
            title += f"  Build {build_number}"
        if subtitle:
            title += f"\n{subtitle}"
        return title



