APP_TITLE = "Schoel Legal Description Generator from DXF"

SCHOEL_LOGO_B64 = """"""

UNDERLINE_PHRASE = "Point of Beginning"

DEFAULT_STATE_LINE = "STATE OF ALABAMA\t)"
DEFAULT_COUNTY_LINE = "COUNTY OF MADISON\t)"
DEFAULT_BOILERPLATE = """A parcel of land situated in Lot 1 of ABC Subdivision (Plat Book 1 Page 100) and in the Southwest Quarter of the Southwest Quarter of Section XX, Township XX South, Range XX West, of the XXXXXXXX Meridian, Madison County, Alabama, {BEARINGS AND/OR DISTANCES referenced to the Alabama State Plane Coordinate System, XXXX Zone, NAD83(2011)} and being more particularly described as follows:"""

def _small_logo_photoimage(master=None):
    try:
        img = tk.PhotoImage(master=master, data=SCHOEL_LOGO_B64)
        w = img.width()
        # target width about 140 px
        factor = max(1, int(round(w / 140)))
        if factor > 1:
            img = img.subsample(factor, factor)
        return img
    except Exception:
        return None

def _area_sentence(area_sqft: float, acres_decimals: int = 3) -> str:
    acres = area_sqft / 43560.0
    sqft_round = round(area_sqft)
    return f"Said parcel contains {acres:.{acres_decimals}f} acres ({sqft_round:,.0f} sq. ft.) more or less."

